// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./TicketNFT.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title EventFactory
 * @dev Factory contract to deploy instances of TicketNFT dynamically.
 */
contract EventFactory is Ownable {
    address[] public deployedEvents;
    address public marketplace;

    event EventCreated(
        address indexed eventAddress,
        string name,
        string symbol,
        uint256 maxSupply,
        uint256 ticketPrice,
        uint256 resalePriceCap,
        address indexed organizer
    );

    constructor(address _marketplace) Ownable(msg.sender) {
        require(_marketplace != address(0), "Invalid marketplace address");
        marketplace = _marketplace;
    }

    /**
     * @notice Deploy a new TicketNFT contract for an event.
     */
    function createEvent(
        string calldata name,
        string calldata symbol,
        uint256 maxSupply,
        uint256 ticketPrice,
        uint256 resalePriceCap,
        address organizer
    ) external returns (address) {
        TicketNFT newEvent = new TicketNFT(
            name,
            symbol,
            maxSupply,
            ticketPrice,
            resalePriceCap,
            organizer
        );

        // Transfer ownership of TicketNFT to the organizer
        newEvent.transferOwnership(organizer);

        address eventAddress = address(newEvent);
        deployedEvents.push(eventAddress);

        emit EventCreated(
            eventAddress,
            name,
            symbol,
            maxSupply,
            ticketPrice,
            resalePriceCap,
            organizer
        );

        return eventAddress;
    }

    /**
     * @notice Get all deployed event addresses.
     */
    function getDeployedEvents() external view returns (address[] memory) {
        return deployedEvents;
    }
}

contracts/TicketMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./TicketNFT.sol";

/**
 * @title TicketMarketplace
 * @dev Secondary market for reselling BlockTicket NFTs with a hard price cap.
 *      Supports multiple TicketNFT contracts deployed by the EventFactory.
 *      Sellers must approve this contract to transfer their NFT before listing.
 *      The original mint price cap (e.g. 110%) is enforced on-chain.
 */
contract TicketMarketplace is Ownable, ReentrancyGuard {

    // ─── Structs ──────────────────────────────────────────────────────────────

    struct Listing {
        address seller;
        uint256 price;     // listing price in wei
        bool    active;
    }

    // ─── State Variables ──────────────────────────────────────────────────────

    uint256 public platformFeePercent; // e.g. 2 = 2%

    // Mapping: nftContract => tokenId => Listing
    mapping(address => mapping(uint256 => Listing)) public listings;

    // Track active listings per contract
    mapping(address => uint256[]) private _activeListingIds;
    // nftContract => tokenId => index in _activeListingIds
    mapping(address => mapping(uint256 => uint256)) private _listingIndexById;

    // ─── Events ───────────────────────────────────────────────────────────────

    event TicketListed(address indexed nftContract, uint256 indexed tokenId, address indexed seller, uint256 price);
    event TicketSold(address indexed nftContract, uint256 indexed tokenId, address indexed buyer, address seller, uint256 price);
    event TicketDelisted(address indexed nftContract, uint256 indexed tokenId, address indexed seller);
    event PriceUpdated(address indexed nftContract, uint256 indexed tokenId, uint256 newPrice);
    event PlatformFeeUpdated(uint256 newFee);
    event PlatformFeesWithdrawn(address indexed to, uint256 amount);

    // ─── Constructor ──────────────────────────────────────────────────────────

    constructor(uint256 platformFee_) Ownable(msg.sender) {
        require(platformFee_ <= 20, "Platform fee cannot exceed 20%");
        platformFeePercent = platformFee_;
    }

    // ─── Seller Functions ─────────────────────────────────────────────────────

    /**
     * @notice List a ticket for resale.
     * @dev Caller must call NFTContract.approve(marketplaceAddress, tokenId) first.
     * @param nftContractAddress Address of the TicketNFT contract
     * @param tokenId Token ID to list
     * @param price   Asking price in wei (must be <= maxResalePrice)
     */
    function listTicket(address nftContractAddress, uint256 tokenId, uint256 price) external {
        TicketNFT nftContract = TicketNFT(payable(nftContractAddress));
        require(nftContract.ownerOf(tokenId) == msg.sender, "You don't own this ticket");
        require(!nftContract.ticketUsed(tokenId), "Used tickets cannot be listed");
        require(!listings[nftContractAddress][tokenId].active, "Already listed");
        require(price > 0, "Price must be > 0");

        // Enforce the price cap from the NFT contract
        uint256 cap = nftContract.maxResalePrice(tokenId);
        require(price <= cap, "Price exceeds resale cap");

        // Verify marketplace is approved to transfer
        require(
            nftContract.getApproved(tokenId) == address(this) ||
            nftContract.isApprovedForAll(msg.sender, address(this)),
            "Marketplace not approved - call NFT.approve() first"
        );

        listings[nftContractAddress][tokenId] = Listing({
            seller: msg.sender,
            price:  price,
            active: true
        });

        _listingIndexById[nftContractAddress][tokenId] = _activeListingIds[nftContractAddress].length;
        _activeListingIds[nftContractAddress].push(tokenId);

        emit TicketListed(nftContractAddress, tokenId, msg.sender, price);
    }

    /**
     * @notice Purchase a listed ticket.
     */
    function buyTicket(address nftContractAddress, uint256 tokenId) external payable nonReentrant {
        Listing storage listing = listings[nftContractAddress][tokenId];
        require(listing.active, "Ticket not listed for sale");
        require(msg.value >= listing.price, "Insufficient MATIC sent");
        require(msg.sender != listing.seller, "Cannot buy your own ticket");

        address seller = listing.seller;
        uint256 price  = listing.price;

        // Remove listing
        _removeListing(nftContractAddress, tokenId);

        // Transfer NFT to buyer
        TicketNFT(payable(nftContractAddress)).transferFrom(seller, msg.sender, tokenId);

        // Distribute funds
        uint256 fee           = (price * platformFeePercent) / 100;
        uint256 sellerPayment = price - fee;

        (bool sellerPaid, ) = payable(seller).call{value: sellerPayment}("");
        require(sellerPaid, "Seller payment failed");

        // Refund excess MATIC to buyer
        if (msg.value > price) {
            (bool refunded, ) = payable(msg.sender).call{value: msg.value - price}("");
            require(refunded, "Refund failed");
        }

        emit TicketSold(nftContractAddress, tokenId, msg.sender, seller, price);
    }

    /**
     * @notice Delist a ticket from resale.
     */
    function delistTicket(address nftContractAddress, uint256 tokenId) external {
        Listing storage listing = listings[nftContractAddress][tokenId];
        require(listing.active, "Not listed");
        require(listing.seller == msg.sender || msg.sender == owner(), "Not authorized");

        _removeListing(nftContractAddress, tokenId);
        emit TicketDelisted(nftContractAddress, tokenId, msg.sender);
    }

    /**
     * @notice Update the price of an existing listing.
     */
    function updatePrice(address nftContractAddress, uint256 tokenId, uint256 newPrice) external {
        Listing storage listing = listings[nftContractAddress][tokenId];
        require(listing.active, "Not listed");
        require(listing.seller == msg.sender, "Not your listing");
        require(newPrice > 0, "Price must be > 0");

        TicketNFT nftContract = TicketNFT(payable(nftContractAddress));
        uint256 cap = nftContract.maxResalePrice(tokenId);
        require(newPrice <= cap, "Price exceeds resale cap");

        listing.price = newPrice;
        emit PriceUpdated(nftContractAddress, tokenId, newPrice);
    }

    // ─── View Functions ───────────────────────────────────────────────────────

    /**
     * @notice Get all active listing token IDs for a specific contract.
     */
    function getActiveListings(address nftContractAddress) external view returns (uint256[] memory) {
        return _activeListingIds[nftContractAddress];
    }

    /**
     * @notice Get listing details for a token in a contract.
     */
    function getListing(address nftContractAddress, uint256 tokenId) external view returns (Listing memory) {
        return listings[nftContractAddress][tokenId];
    }

    // ─── Admin Functions ──────────────────────────────────────────────────────

    function setPlatformFee(uint256 newFee) external onlyOwner {
        require(newFee <= 20, "Fee cannot exceed 20%");
        platformFeePercent = newFee;
        emit PlatformFeeUpdated(newFee);
    }

    function withdrawFees() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");
        (bool sent, ) = payable(owner()).call{value: balance}("");
        require(sent, "Withdrawal failed");
        emit PlatformFeesWithdrawn(owner(), balance);
    }

    // ─── Internal Helpers ─────────────────────────────────────────────────────

    function _removeListing(address nftContractAddress, uint256 tokenId) internal {
        uint256 idx = _listingIndexById[nftContractAddress][tokenId];
        uint256 lastId = _activeListingIds[nftContractAddress][_activeListingIds[nftContractAddress].length - 1];

        _activeListingIds[nftContractAddress][idx] = lastId;
        _listingIndexById[nftContractAddress][lastId] = idx;

        _activeListingIds[nftContractAddress].pop();
        delete _listingIndexById[nftContractAddress][tokenId];
        delete listings[nftContractAddress][tokenId];
    }

    receive() external payable {}
}

contracts/TicketNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TicketNFT
 * @dev ERC-721 NFT contract for event tickets on BlockTicket platform.
 *      Each token represents one ticket. Tickets can be minted (purchased),
 *      burned (destroyed on gate entry), or marked used (soft invalidation).
 */
contract TicketNFT is
    ERC721,
    ERC721URIStorage,
    ERC721Enumerable,
    Ownable,
    Pausable,
    ReentrancyGuard
{
    // ─── State Variables ──────────────────────────────────────────────────────

    uint256 private _tokenIdCounter;

    uint256 public maxSupply;
    uint256 public ticketPrice;        // in wei (MATIC)
    uint256 public resalePriceCap;     // percentage, e.g. 110 = 110% of original
    address public organizer;
    bool    public saleActive;

    mapping(uint256 => bool)    public ticketUsed;
    mapping(uint256 => uint256) public mintPrice;  // original price per token (wei)

    // ─── Events ───────────────────────────────────────────────────────────────

    event TicketMinted(address indexed buyer, uint256 indexed tokenId, string tokenURI, uint256 price);
    event TicketBurned(uint256 indexed tokenId, address indexed burner);
    event TicketMarkedUsed(uint256 indexed tokenId);
    event SaleToggled(bool active);
    event FundsWithdrawn(address indexed to, uint256 amount);
    event PriceUpdated(uint256 newPrice);
    event MaxSupplyUpdated(uint256 newMaxSupply);

    // ─── Modifiers ────────────────────────────────────────────────────────────

    modifier onlyOrganizer() {
        require(msg.sender == organizer || msg.sender == owner(), "Not authorized");
        _;
    }

    modifier whenSaleActive() {
        require(saleActive, "Sale is not active");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────

    /**
     * @param name_          NFT collection name (e.g. "Coldplay World Tour Tickets")
     * @param symbol_        NFT symbol (e.g. "CWT")
     * @param maxSupply_     Total number of tickets available
     * @param ticketPrice_   Price per ticket in wei
     * @param resalePriceCap_ Max resale % (e.g. 110 = 110% of original price)
     * @param organizer_     Address of the event organizer
     */
    constructor(
        string memory name_,
        string memory symbol_,
        uint256 maxSupply_,
        uint256 ticketPrice_,
        uint256 resalePriceCap_,
        address organizer_
    ) ERC721(name_, symbol_) Ownable(msg.sender) {
        require(maxSupply_ > 0, "Max supply must be > 0");
        require(organizer_ != address(0), "Invalid organizer address");
        require(resalePriceCap_ >= 100, "Resale cap must be >= 100%");

        maxSupply     = maxSupply_;
        ticketPrice   = ticketPrice_;
        resalePriceCap = resalePriceCap_;
        organizer     = organizer_;
        saleActive    = false;
    }

    // ─── Core Functions ───────────────────────────────────────────────────────

    /**
     * @notice Mint one ticket NFT.
     * @param tokenURI_ IPFS metadata URI for this ticket (ipfs://CID)
     */
    function mintTicket(string calldata tokenURI_)
        external
        payable
        nonReentrant
        whenNotPaused
        whenSaleActive
        returns (uint256)
    {
        require(totalSupply() < maxSupply, "All tickets sold out");
        require(msg.value >= ticketPrice, "Insufficient MATIC sent");

        uint256 tokenId = _tokenIdCounter;
        _tokenIdCounter++;

        _safeMint(msg.sender, tokenId);
        _setTokenURI(tokenId, tokenURI_);

        mintPrice[tokenId] = msg.value;
        ticketUsed[tokenId] = false;

        // Refund excess payment
        if (msg.value > ticketPrice) {
            uint256 excess = msg.value - ticketPrice;
            (bool refunded, ) = payable(msg.sender).call{value: excess}("");
            require(refunded, "Refund failed");
        }

        emit TicketMinted(msg.sender, tokenId, tokenURI_, ticketPrice);
        return tokenId;
    }

    /**
     * @notice Burn a ticket on gate entry (destroys the NFT permanently).
     * @param tokenId Token ID to burn
     */
    function burnTicket(uint256 tokenId) external {
        require(
            ownerOf(tokenId) == msg.sender || msg.sender == organizer || msg.sender == owner(),
            "Not authorized to burn"
        );
        require(!ticketUsed[tokenId], "Ticket already used");

        ticketUsed[tokenId] = true;
        _burn(tokenId);

        emit TicketBurned(tokenId, msg.sender);
    }

    /**
     * @notice Mark ticket as used (soft invalidation — keeps the NFT).
     * @param tokenId Token ID to mark used
     */
    function markUsed(uint256 tokenId) external onlyOrganizer {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        require(!ticketUsed[tokenId], "Already marked used");

        ticketUsed[tokenId] = true;
        emit TicketMarkedUsed(tokenId);
    }

    /**
     * @notice Verify ticket details (ownership + used status).
     * @return tokenOwner Address of the ticket owner
     * @return isUsed     Whether the ticket has been used
     * @return uri        Token metadata URI
     */
    function verifyTicket(uint256 tokenId)
        external
        view
        returns (
            address tokenOwner,
            bool    isUsed,
            string  memory uri
        )
    {
        require(_ownerOf(tokenId) != address(0), "Token does not exist");
        return (ownerOf(tokenId), ticketUsed[tokenId], tokenURI(tokenId));
    }

    /**
     * @notice Get all token IDs owned by an address.
     */
    function tokensByOwner(address owner_) external view returns (uint256[] memory) {
        uint256 count = balanceOf(owner_);
        uint256[] memory tokens = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            tokens[i] = tokenOfOwnerByIndex(owner_, i);
        }
        return tokens;
    }

    /**
     * @notice Get the max resale price allowed for a token (in wei).
     */
    function maxResalePrice(uint256 tokenId) external view returns (uint256) {
        return (mintPrice[tokenId] * resalePriceCap) / 100;
    }

    // ─── Admin Functions ──────────────────────────────────────────────────────

    function toggleSale() external onlyOrganizer {
        saleActive = !saleActive;
        emit SaleToggled(saleActive);
    }

    function setMaxSupply(uint256 newMaxSupply) external onlyOwner {
        require(newMaxSupply >= totalSupply(), "Cannot reduce below minted count");
        maxSupply = newMaxSupply;
        emit MaxSupplyUpdated(newMaxSupply);
    }

    function setTicketPrice(uint256 newPrice) external onlyOwner {
        ticketPrice = newPrice;
        emit PriceUpdated(newPrice);
    }

    function setResalePriceCap(uint256 newCap) external onlyOwner {
        require(newCap >= 100, "Cap must be >= 100%");
        resalePriceCap = newCap;
    }

    function setOrganizer(address newOrganizer) external onlyOwner {
        require(newOrganizer != address(0), "Invalid address");
        organizer = newOrganizer;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Withdraw all contract funds to the organizer wallet.
     */
    function withdrawFunds() external onlyOrganizer nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No funds to withdraw");

        (bool sent, ) = payable(organizer).call{value: balance}("");
        require(sent, "Withdrawal failed");

        emit FundsWithdrawn(organizer, balance);
    }

    // ─── ERC721 Overrides ─────────────────────────────────────────────────────

    function _update(address to, uint256 tokenId, address auth)
        internal
        override(ERC721, ERC721Enumerable)
        returns (address)
    {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value)
        internal
        override(ERC721, ERC721Enumerable)
    {
        super._increaseBalance(account, value);
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage, ERC721Enumerable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    receive() external payable {}
}

